 @Inject(method="<init>(Lnet/minecraft/world/level/levelgen/structure/templatesystem/StructureTemplateManager;Lnet/minecraft/nbt/CompoundTag;)V",at=@At("TAIL")) private void read(StructureTemplateManager manager,CompoundTag tag,CallbackInfo ci){if(tag.contains("blockbranch:snow_shelter_v1")){blockbranch$variant=tag.getIntOr("blockbranch:snow_shelter_v1",-1);if(blockbranch$variant<0||blockbranch$variant>1)throw new IllegalArgumentException("Invalid saved snow shelter variant");if(blockbranch$shelterTop())boundingBox.encapsulate(new BlockPos(boundingBox.maxX(),templatePosition.getY()+5,boundingBox.maxZ()));}if(tag.contains("blockbranch:native_igloo_v1")){if(tag.getIntOr("blockbranch:native_igloo_v1",0)!=1||blockbranch$variant>=0)throw new IllegalArgumentException("Invalid native igloo body marker");blockbranch$nativeBody=true;}}
